package main

import (
	"crypto/rand"
	"encoding/hex"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"regexp"
	"strings"
	"sync"
	"time"
)

const (
	storageRoot = "/var/app/storage"
	maxFileSize = 10 * 1024 * 1024
)

var (
	validFilename = regexp.MustCompile(`^[a-zA-Z0-9][a-zA-Z0-9._-]{0,254}$`)
	uploadLocks   sync.Map
)

// generateToken creates a cryptographically random token
func generateToken() (string, error) {
	b := make([]byte, 16)
	if _, err := rand.Read(b); err != nil {
		return "", fmt.Errorf("cannot generate secure token: %w", err)
	}
	return hex.EncodeToString(b), nil
}

// getUserDir returns the user-specific storage directory
func getUserDir(userID string) string {
	// Sanitize userID to prevent traversal
	safeID := strings.ReplaceAll(userID, "..", "")
	safeID = strings.ReplaceAll(safeID, "/", "")
	safeID = strings.ReplaceAll(safeID, "\\", "")
	if safeID == "" {
		safeID = "anonymous"
	}
	return filepath.Join(storageRoot, safeID)
}

// validatePath ensures the resolved path is within the storage root
func validatePath(path string) error {
	absPath, err := filepath.Abs(path)
	if err != nil {
		return fmt.Errorf("invalid path")
	}
	// Use filepath.Rel to check containment - more robust than HasPrefix
	rel, err := filepath.Rel(storageRoot, absPath)
	if err != nil {
		return fmt.Errorf("path outside storage")
	}
	if strings.HasPrefix(rel, "..") {
		return fmt.Errorf("path traversal detected")
	}
	return nil
}

// ensureDirectory creates directory if it doesn't exist
func ensureDirectory(dir string) error {
	return os.MkdirAll(dir, 0750)
}

// safeWriteFile writes content to a file atomically using O_NOFOLLOW
// and writing to a temp file then renaming
func safeWriteFile(targetPath string, content []byte) error {
	// Security check: verify target path is within storage
	if err := validatePath(targetPath); err != nil {
		return err
	}

	dir := filepath.Dir(targetPath)
	if err := ensureDirectory(dir); err != nil {
		return fmt.Errorf("cannot create directory: %w", err)
	}

	// Atomic write: create temp file in same directory, then rename
	// This prevents TOCTOU races with symlinks
	tmpFile, err := os.CreateTemp(dir, ".tmp-upload-*")
	if err != nil {
		return fmt.Errorf("cannot create temp file: %w", err)
	}
	tmpPath := tmpFile.Name()

	// Ensure cleanup on failure
	success := false
	defer func() {
		if !success {
			os.Remove(tmpPath)
		}
	}()

	// Set permissions before writing content
	if err := tmpFile.Chmod(0640); err != nil {
		tmpFile.Close()
		return fmt.Errorf("cannot set permissions: %w", err)
	}

	_, err = tmpFile.Write(content)
	tmpFile.Close()
	if err != nil {
		return fmt.Errorf("write error: %w", err)
	}

	// Atomic rename - this replaces any existing file (including symlinks)
	// atomically, preventing TOCTOU races
	if err := os.Rename(tmpPath, targetPath); err != nil {
		return fmt.Errorf("rename failed: %w", err)
	}

	success = true
	return nil
}

// safeReadFile reads a file using O_NOFOLLOW semantics
func safeReadFile(targetPath string) ([]byte, error) {
	// Security check: verify target path is within storage
	if err := validatePath(targetPath); err != nil {
		return nil, err
	}

	// Open with O_NOFOLLOW to prevent symlink following
	// Note: We use Lstat + Open with the file descriptor to avoid TOCTOU
	info, err := os.Lstat(targetPath)
	if err != nil {
		return nil, fmt.Errorf("file not found")
	}
	if !info.Mode().IsRegular() {
		return nil, fmt.Errorf("target is not a regular file")
	}

	// Open the file - on Linux, O_NOFOLLOW prevents following symlinks
	f, err := os.OpenFile(targetPath, os.O_RDONLY|0x20000, 0) // 0x20000 = O_NOFOLLOW on Linux
	if err != nil {
		return nil, fmt.Errorf("cannot open file: %w", err)
	}
	defer f.Close()

	// Verify the opened file descriptor matches what we expect
	fInfo, err := f.Stat()
	if err != nil {
		return nil, fmt.Errorf("cannot stat fd: %w", err)
	}
	if !fInfo.Mode().IsRegular() {
		return nil, fmt.Errorf("fd is not a regular file")
	}

	return io.ReadAll(f)
}

func uploadHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	userID := r.Header.Get("X-Authenticated-User")
	if userID == "" {
		http.Error(w, "Unauthorized", http.StatusUnauthorized)
		return
	}

	filename := r.URL.Query().Get("name")
	if !validFilename.MatchString(filename) {
		http.Error(w, "Invalid filename", http.StatusBadRequest)
		return
	}

	// Rate limiting per user
	lockKey := userID + ":" + filename
	if _, loaded := uploadLocks.LoadOrStore(lockKey, time.Now()); loaded {
		http.Error(w, "Upload in progress", http.StatusConflict)
		return
	}
	defer uploadLocks.Delete(lockKey)

	// Read body with size limit
	limitedReader := io.LimitReader(r.Body, maxFileSize)
	content, err := io.ReadAll(limitedReader)
	if err != nil {
		http.Error(w, "Read error", http.StatusInternalServerError)
		return
	}

	userDir := getUserDir(userID)
	targetPath := filepath.Join(userDir, filename)

	if err := safeWriteFile(targetPath, content); err != nil {
		http.Error(w, err.Error(), http.StatusForbidden)
		return
	}

	w.WriteHeader(http.StatusCreated)
	fmt.Fprintf(w, "File uploaded: %s\n", filename)
}

func downloadHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	userID := r.Header.Get("X-Authenticated-User")
	if userID == "" {
		http.Error(w, "Unauthorized", http.StatusUnauthorized)
		return
	}

	filename := r.URL.Query().Get("name")
	if !validFilename.MatchString(filename) {
		http.Error(w, "Invalid filename", http.StatusBadRequest)
		return
	}

	userDir := getUserDir(userID)
	targetPath := filepath.Join(userDir, filename)

	data, err := safeReadFile(targetPath)
	if err != nil {
		http.Error(w, err.Error(), http.StatusForbidden)
		return
	}

	w.Header().Set("Content-Type", "application/octet-stream")
	w.Write(data)
}

func deleteHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodDelete {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	userID := r.Header.Get("X-Authenticated-User")
	if userID == "" {
		http.Error(w, "Unauthorized", http.StatusUnauthorized)
		return
	}

	filename := r.URL.Query().Get("name")
	if !validFilename.MatchString(filename) {
		http.Error(w, "Invalid filename", http.StatusBadRequest)
		return
	}

	userDir := getUserDir(userID)
	targetPath := filepath.Join(userDir, filename)

	// Validate path containment
	if err := validatePath(targetPath); err != nil {
		http.Error(w, err.Error(), http.StatusForbidden)
		return
	}

	// Atomic check: use Lstat on the path, then remove
	// Even if a race occurs, Remove on a symlink just removes the link itself
	info, err := os.Lstat(targetPath)
	if err != nil {
		http.Error(w, "File not found", http.StatusNotFound)
		return
	}
	if !info.Mode().IsRegular() {
		http.Error(w, "Cannot delete non-regular file", http.StatusForbidden)
		return
	}

	// Remove - safe because even if replaced with symlink between check and remove,
	// os.Remove on a symlink only removes the symlink itself, not the target
	if err := os.Remove(targetPath); err != nil {
		http.Error(w, "Delete failed", http.StatusInternalServerError)
		return
	}

	w.WriteHeader(http.StatusOK)
	fmt.Fprintf(w, "File deleted: %s\n", filename)
}

func main() {
	http.HandleFunc("/upload", uploadHandler)
	http.HandleFunc("/download", downloadHandler)
	http.HandleFunc("/delete", deleteHandler)

	fmt.Println("Secure file server starting on :8443")
	if err := http.ListenAndServe(":8443", nil); err != nil {
		fmt.Printf("server error: %v\n", err)
	}
}
